using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Text;
using System.Windows.Forms;

namespace TokenGrove {
  public sealed class Palette {
    public Color Bg,Panel,Side,Text,Muted,Line,Green,Soft,Coral,Mint,Subtle,Hover,Warning,WarningSoft;
    public int SurfaceOpacity=100;
    public Color SurfaceTint{get{return Color.FromArgb((int)Math.Round(SurfaceOpacity*2.55),Panel);}}
    public Palette(bool dark){Bg=C(dark?"#181C24":"#E9EDF4");Panel=C(dark?"#232833":"#F9FAFD");Side=C(dark?"#1C212B":"#EDF0F6");Text=C(dark?"#EBEFF7":"#263044");Muted=C(dark?"#A7B0C2":"#667389");Line=C(dark?"#353E4F":"#DAE0EB");Green=C(dark?"#9CB6FF":"#536FCB");Soft=C(dark?"#303D59":"#E5EBFC");Coral=C(dark?"#D4A591":"#BD8E7B");Mint=C(dark?"#9AB5E2":"#7C98C5");Subtle=C(dark?"#7E8AA0":"#8793A8");Hover=C(dark?"#292F3C":"#F0F3F9");Warning=C(dark?"#EEB77A":"#B97539");WarningSoft=C(dark?"#443529":"#FAEEDF");}
    public static Color C(string hex){return ColorTranslator.FromHtml(hex);}
  }
  public static class Art {
    public static bool AnimationsEnabled=true;
    static readonly System.Collections.Generic.Dictionary<string,Font> fontCache=new System.Collections.Generic.Dictionary<string,Font>();
    public static Font Font(float size,bool bold=false){return Typography.Font(size,bold);}
    public static Font CachedFont(float size,bool bold=false){string key=size.ToString(System.Globalization.CultureInfo.InvariantCulture)+(bold?"b":"r");Font f;if(!fontCache.TryGetValue(key,out f)){f=Font(size,bold);fontCache[key]=f;}return f;}
    public static GraphicsPath Round(RectangleF r,float radius=12){var p=new GraphicsPath();float d=radius*2;if(r.Width<d||r.Height<d){p.AddRectangle(r);return p;}p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
    public static void Box(Graphics g,RectangleF r,Color color,Color? border=null,float radius=12){using(var p=Round(r,radius)){using(var b=new SolidBrush(color))g.FillPath(b,p);if(border.HasValue)using(var pen=new Pen(border.Value,1))g.DrawPath(pen,p);}}
    public static Color Mix(Color a,Color b,float t){t=Math.Max(0,Math.Min(1,t));return Color.FromArgb((int)(a.A+(b.A-a.A)*t),(int)(a.R+(b.R-a.R)*t),(int)(a.G+(b.G-a.G)*t),(int)(a.B+(b.B-a.B)*t));}
    public static void Surface(Graphics g,RectangleF r,Palette p,float radius=18,float hover=0){Box(g,r,Color.FromArgb(p.SurfaceTint.A,Mix(p.Panel,p.Hover,hover*.3f)),p.Line,radius);}
    public static void Tint(Graphics g,RectangleF r,Color top,Color bottom,float radius=16){using(var path=Round(r,radius))using(var brush=new LinearGradientBrush(r,top,bottom,90f))g.FillPath(brush,path);}
    public static void Pill(Graphics g,string text,RectangleF rect,Color fill,Color ink,float size=10){Box(g,rect,fill,null,rect.Height/2);Text(g,text,rect.X,rect.Y+(rect.Height-size)/2-1,size,ink,true,rect.Width,StringAlignment.Center);}
    public static void Icon(Graphics g,string name,float x,float y,float size,Color color){var state=g.Save();g.TranslateTransform(x,y);g.ScaleTransform(size/24,size/24);using(var pen=new Pen(color,1.65f){StartCap=LineCap.Round,EndCap=LineCap.Round,LineJoin=LineJoin.Round}){switch(name){case "overview":g.DrawRectangle(pen,3,3,7,7);g.DrawRectangle(pen,14,3,7,7);g.DrawRectangle(pen,3,14,7,7);g.DrawRectangle(pen,14,14,7,7);break;case "models":g.DrawPolygon(pen,new[]{new PointF(12,3),new PointF(22,8),new PointF(12,13),new PointF(2,8)});g.DrawLines(pen,new[]{new PointF(3,12),new PointF(12,17),new PointF(21,12)});g.DrawLines(pen,new[]{new PointF(3,16),new PointF(12,21),new PointF(21,16)});break;case "accounts":g.DrawEllipse(pen,8,3,8,8);g.DrawArc(pen,4,13,16,14,180,180);break;case "history":g.DrawArc(pen,3,3,18,18,205,320);g.DrawLines(pen,new[]{new PointF(3,3),new PointF(3,9),new PointF(9,9)});g.DrawLines(pen,new[]{new PointF(12,7),new PointF(12,12),new PointF(16,14)});break;case "settings":g.DrawEllipse(pen,4,4,16,16);g.DrawEllipse(pen,9,9,6,6);for(int i=0;i<8;i++){double a=i*Math.PI/4;g.DrawLine(pen,12+(float)Math.Cos(a)*8,12+(float)Math.Sin(a)*8,12+(float)Math.Cos(a)*10,12+(float)Math.Sin(a)*10);}break;case "expand":g.DrawLines(pen,new[]{new PointF(14,4),new PointF(20,4),new PointF(20,10)});g.DrawLine(pen,20,4,10,14);g.DrawLines(pen,new[]{new PointF(6,6),new PointF(4,6),new PointF(4,20),new PointF(18,20),new PointF(18,18)});break;case "refresh":g.DrawArc(pen,4,4,16,16,35,290);g.DrawLines(pen,new[]{new PointF(20,4),new PointF(20,10),new PointF(14,10)});break;case "close":g.DrawLine(pen,7,7,17,17);g.DrawLine(pen,17,7,7,17);break;case "more":for(int i=0;i<3;i++)g.DrawEllipse(pen,4+i*7,11,1,1);break;case "calendar":g.DrawRectangle(pen,3,5,18,16);g.DrawLine(pen,3,10,21,10);g.DrawLine(pen,8,2,8,7);g.DrawLine(pen,16,2,16,7);g.DrawRectangle(pen,7,14,3,3);break;case "clock":g.DrawEllipse(pen,3,3,18,18);g.DrawLines(pen,new[]{new PointF(12,7),new PointF(12,12),new PointF(16,14)});break;case "search":g.DrawEllipse(pen,3,3,12,12);g.DrawLine(pen,13,13,21,21);break;case "download":g.DrawLines(pen,new[]{new PointF(6,11),new PointF(12,17),new PointF(18,11)});g.DrawLine(pen,12,3,12,17);g.DrawLines(pen,new[]{new PointF(4,17),new PointF(4,21),new PointF(20,21),new PointF(20,17)});break;case "leaf":g.DrawArc(pen,5,4,15,15,0,270);g.DrawLines(pen,new[]{new PointF(5,20),new PointF(19,6),new PointF(20,3)});break;case "laptop":g.DrawRectangle(pen,4,3,16,13);g.DrawPolygon(pen,new[]{new PointF(4,16),new PointF(1,20),new PointF(23,20),new PointF(20,16)});break;default:g.DrawEllipse(pen,3,3,18,18);g.DrawLine(pen,12,10,12,17);g.DrawEllipse(pen,11.5f,6,1,1);break;}}g.Restore(state);}
    public static void Text(Graphics g,string text,float x,float y,float size,Color color,bool bold=false,float width=0,StringAlignment align=StringAlignment.Near){Typography.Prepare(g);var f=CachedFont(size,bold);using(var b=new SolidBrush(color))using(var fmt=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap,Alignment=align}){if(width>0)g.DrawString(text??"",f,b,new RectangleF(x,y,width,Math.Max(size*2,f.GetHeight(g)+2)),fmt);else g.DrawString(text??"",f,b,x,y);}}
    public static void Lines(Graphics g,string text,RectangleF rect,float size,Color color){Typography.Prepare(g);var f=CachedFont(size);using(var b=new SolidBrush(color))using(var fmt=new StringFormat{Trimming=StringTrimming.EllipsisCharacter})g.DrawString(text??"",f,b,rect,fmt);}
    public static void Line(Graphics g,float x1,float y1,float x2,float y2,Color color){using(var p=new Pen(color))g.DrawLine(p,x1,y1,x2,y2);}
    public static void Dot(Graphics g,float x,float y,Color color,float size=5){using(var b=new SolidBrush(color))g.FillEllipse(b,x,y,size,size);}
    public static void Clover(Graphics g,float x,float y,float size,Color color){float q=size*.45f;Box(g,new RectangleF(x,y,q,q),color,null,q*.35f);Box(g,new RectangleF(x+size-q,y,q,q),color,null,q*.35f);Box(g,new RectangleF(x,y+size-q,q,q),color,null,q*.35f);Box(g,new RectangleF(x+size-q,y+size-q,q,q),color,null,q*.35f);}
    public static void QuotaColors(double percent,out Color start,out Color end){if(percent<60){start=Palette.C("#8BB7F1");end=Palette.C("#647DE0");}else if(percent<85){start=Palette.C("#EDC58E");end=Palette.C("#DEA361");}else{start=Palette.C("#EDAAA3");end=Palette.C("#D7667A");}}
    public static void Progress(Graphics g,RectangleF rect,double? percent,Color color,Palette p){Box(g,rect,p.Line,null,rect.Height/2);if(percent.HasValue&&percent>0){var r=rect;r.Width=Math.Max(rect.Height,(float)(rect.Width*Math.Min(100,percent.Value)/100));Color start,end;QuotaColors(percent.Value,out start,out end);using(var path=Round(r,rect.Height/2))using(var brush=new LinearGradientBrush(r,start,end,0f))g.FillPath(brush,path);}else if(!percent.HasValue){var saved=g.Save();g.SetClip(rect);using(var pen=new Pen(p.Subtle,1)){for(float x=rect.X-rect.Height;x<rect.Right;x+=9)g.DrawLine(pen,x,rect.Y,x+rect.Height,rect.Bottom);}g.Restore(saved);}}
    public static void Mascot(Graphics g,RectangleF rect,bool claude,bool blink=false,float bob=0,float energy=0){
      var saved=g.Save();g.TranslateTransform(rect.X,rect.Y+bob);g.ScaleTransform(rect.Width/160f,rect.Height/160f);g.SmoothingMode=SmoothingMode.AntiAlias;
      using(var shadow=new SolidBrush(Color.FromArgb(20,87,114,72)))g.FillEllipse(shadow,49,139,63,8);
      if(claude){using(var pen=new Pen(Palette.C("#b67d5c"),4.8f)){pen.StartCap=pen.EndCap=LineCap.Round;g.DrawLines(pen,new[]{new PointF(61,112),new PointF(58,134),new PointF(49,136)});g.DrawLines(pen,new[]{new PointF(98,113),new PointF(103,133),new PointF(112,133)});g.DrawLines(pen,new[]{new PointF(38,86),new PointF(22,99),new PointF(20,88)});g.DrawLines(pen,new[]{new PointF(120,84),new PointF(136+energy*3,69-energy*8),new PointF(139+energy*3,77-energy*8)});}
        var points=new PointF[24];for(int i=0;i<24;i++){double a=-Math.PI/2+i*Math.PI/12;float radius=i%2==0?62:43;points[i]=new PointF(80+(float)Math.Cos(a)*radius,77+(float)Math.Sin(a)*radius);}using(var b=new SolidBrush(Palette.C("#e3ad88")))g.FillPolygon(b,points);using(var p=new Pen(Palette.C("#ce956d"),1.6f))g.DrawPolygon(p,points);
        using(var brush=new SolidBrush(Palette.C("#674b34"))){g.FillEllipse(brush,62,blink?79:74,6,blink?2:9);g.FillEllipse(brush,92,blink?79:74,6,blink?2:9);}using(var pen=new Pen(Palette.C("#79503a"),2.4f))g.DrawArc(pen,75,84,12,10,10,160);using(var b=new SolidBrush(Color.FromArgb(85,207,117,92))){g.FillEllipse(b,50,87,12,6);g.FillEllipse(b,104,86,12,6);}
      }else{using(var pen=new Pen(Palette.C("#739474"),4.7f)){pen.StartCap=pen.EndCap=LineCap.Round;g.DrawLines(pen,new[]{new PointF(61,116),new PointF(59,134),new PointF(51,135)});g.DrawLines(pen,new[]{new PointF(98,116),new PointF(103,134),new PointF(111,134)});g.DrawLines(pen,new[]{new PointF(42,87),new PointF(24,97),new PointF(20,88)});g.DrawLines(pen,new[]{new PointF(119,84),new PointF(133,71),new PointF(139,78)});g.DrawLine(pen,82,51,84,34);}
        using(var b=new SolidBrush(Palette.C("#8eab72"))){g.FillEllipse(b,66,23,16,23);g.FillEllipse(b,82,16,21,28);}Box(g,new RectangleF(36,46,89,83),Palette.C("#a6c29f"),Palette.C("#819f7e"),25);Box(g,new RectangleF(45,65,70,40),Palette.C("#e8eed8"),Palette.C("#92ac87"),12);
        using(var b=new SolidBrush(Palette.C("#596c4e"))){g.FillEllipse(b,63,blink?81:77,5,blink?2:9);g.FillEllipse(b,92,blink?81:77,5,blink?2:9);}using(var pen=new Pen(Palette.C("#7a8c61"),2.2f))g.DrawArc(pen,75,86,11,8,10,160);using(var b=new SolidBrush(Palette.C("#cdb09a"))){g.FillEllipse(b,53,90,11,5);g.FillEllipse(b,101,90,11,5);}Box(g,new RectangleF(68,111,23,6),Palette.C("#86a47a"),null,3);
      }g.Restore(saved);
    }
    public static Icon MakeIcon(){using(var bitmap=new Bitmap(32,32)){using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=SmoothingMode.AntiAlias;Box(g,new RectangleF(0,0,32,32),Palette.C("#E9EEFA"),null,8);Clover(g,7,7,18,Palette.C("#637BCB"));}var h=bitmap.GetHicon();try{return (System.Drawing.Icon)System.Drawing.Icon.FromHandle(h).Clone();}finally{Native.DestroyIcon(h);}}}
  }
}
